[
  {
    "severity": "high",
    "issue": "Project Center information architecture is too technical for first-run users",
    "why_it_matters": "Mixing project creation/opening, sidecar health, and profile/model configuration in one entry screen increases cognitive load and makes the app feel like an engineering console rather than a research copilot. Users may not know what is required versus optional before starting work.",
    "recommended_fix": "Separate the screen into a primary project-start area and a secondary advanced configuration area. Make create/open project the dominant action, collapse profile/model settings under '高级设置', and add brief plain-language descriptions for required fields."
  },
  {
    "severity": "medium",
    "issue": "Profile/model form likely exposes implementation details instead of user goals",
    "why_it_matters": "If users see raw model/provider terminology too early, they must translate technical settings into research intent. This slows onboarding and reduces perceived professionalism.",
    "recommended_fix": "Reframe the form around outcomes such as speed, quality, and privacy. Provide sensible defaults, presets, and inline helper text in Chinese. Keep raw provider/model controls behind an advanced expander."
  },
  {
    "severity": "high",
    "issue": "Runtime unavailable state may not provide a clear recovery path",
    "why_it_matters": "A status indicator without a direct next action leaves users blocked, especially in desktop environments where sidecar/runtime installation is a prerequisite. This is a critical empty-state failure.",
    "recommended_fix": "Turn the unavailable state into an action-oriented empty state with explicit buttons such as '安装运行时', '配置路径', and '重试检测'. Include a short explanation, current detected status, and link to logs/details."
  },
  {
    "severity": "medium",
    "issue": "Workspace contains many concurrent regions with weak hierarchy",
    "why_it_matters": "Three-phase progress, material intake, next-step prompt, execution stream, approvals, archive, and final output all compete for attention. Users may struggle to identify the single current task.",
    "recommended_fix": "Establish a stronger task hierarchy: pin the current step and required action at the top, keep passive observability panels secondary, and progressively reveal archive/debug information. Use one dominant call-to-action per phase."
  },
  {
    "severity": "medium",
    "issue": "Acceptance/next-step prompt may be ambiguous as an empty or transitional state",
    "why_it_matters": "When the system pauses for user choice, the app must clearly communicate what happened, what is waiting, and what each option will do. Ambiguity causes hesitation and accidental progression.",
    "recommended_fix": "Present this state as a decision card with a clear summary, consequences of each choice, recommended option, and keyboard-default focus on the safest action."
  },
  {
    "severity": "low",
    "issue": "Final product modal defaulting to report may bias users away from better output types",
    "why_it_matters": "A default recommendation strongly influences selection. If 'report' is preselected too often, users may miss archives or structured outputs better suited to their task.",
    "recommended_fix": "Only recommend 'report' when confidence is high and explain why. Otherwise use a neutral default, show 2–3 output types with use-case labels, and remember the user's last choice."
  },
  {
    "severity": "medium",
    "issue": "Empty states in archive and approval areas may still feel system-centric",
    "why_it_matters": "Panels that are empty without explanation appear unfinished. Users need to know when content will appear and whether they must take action.",
    "recommended_fix": "Add explicit empty states such as '暂无待审批操作' with a note on what triggers approvals, and '暂无归档快照' with when snapshots are created. Include subtle icons and one-line guidance."
  },
  {
    "severity": "high",
    "issue": "Keyboard flow is likely weak across complex multi-panel workspace interactions",
    "why_it_matters": "Desktop power users expect full keyboard operation. Streams, approval actions, expandable JSON, dialogs, and modals can easily create focus traps or inefficient tab order if not intentionally designed.",
    "recommended_fix": "Define a predictable tab order, visible focus states, Enter/Esc behavior, arrow-key navigation for lists/cards, and shortcuts for core actions like approve/decline, expand details, open project, and retry runtime checks."
  },
  {
    "severity": "high",
    "issue": "Accessibility risk in event cards, approval cards, and expandable JSON",
    "why_it_matters": "Readable cards are an improvement, but if expand/collapse state, semantic labels, and screen-reader announcements are missing, critical execution information remains inaccessible.",
    "recommended_fix": "Use proper button semantics with aria-expanded, label action buttons clearly, announce new runtime events in a polite live region, and ensure JSON/detail panes are navigable and copyable by keyboard."
  },
  {
    "severity": "medium",
    "issue": "Narrow window usability is at risk due to dense multi-pane layout",
    "why_it_matters": "Desktop apps are frequently snapped to half-screen widths on Windows. Simultaneous panels can become cramped, causing truncation, horizontal scrolling, and loss of action clarity.",
    "recommended_fix": "Introduce responsive breakpoints for narrow widths: stack secondary panels below the main task area, collapse archive/debug sections into tabs or drawers, preserve sticky primary actions, and aggressively manage text truncation with tooltips."
  },
  {
    "severity": "medium",
    "issue": "Visual professionalism may still be inconsistent if system, debug, and product UI are visually mixed",
    "why_it_matters": "When operational diagnostics share the same visual weight as user-facing workflow steps, the product can feel unfinished or internal. This reduces trust in a research assistant context.",
    "recommended_fix": "Differentiate user workflow surfaces from diagnostic surfaces with a clearer type scale, spacing system, subdued debug styling, and consistent card/action patterns. Reserve high-contrast emphasis for current task and risk states only."
  },
  {
    "severity": "low",
    "issue": "Chinese-first localization is good, but mixed fallback strings remain a professionalism risk",
    "why_it_matters": "Even with mojibake protection and fixed phase labels, any remaining English/internal terminology breaks flow and signals incomplete polish.",
    "recommended_fix": "Run a full localization pass on status text, approval metadata labels, dialog fallback text, and error states. Standardize terminology and ensure truncation rules work for Chinese in narrow layouts."
  }
]

{
  "risks": [
    {
      "area": "permissions",
      "risk": "Approval cards are richer now, but users may still approve high-impact actions without understanding persistence, reversibility, or blast radius.",
      "severity": "high"
    },
    {
      "area": "approval_ux",
      "risk": "Allow/decline/cancel exists, but the distinction between decline vs cancel may be unclear during live execution, increasing accidental blocking or unintended continuation.",
      "severity": "medium"
    },
    {
      "area": "archive_ux",
      "risk": "Archive preview improves transparency, but recovery value is limited if users cannot clearly restore, re-open, diff, or resume from a specific archived state.",
      "severity": "high"
    },
    {
      "area": "runtime_unavailable",
      "risk": "If Python sidecar/Codex runtime is unavailable, users may hit a dead-end state without a single obvious repair path, especially on Windows installs with env/config issues.",
      "severity": "high"
    },
    {
      "area": "retry_continue",
      "risk": "Interruption handling appears visible in the stream, but resume semantics may still be ambiguous: retry last step, continue from checkpoint, or restart full run.",
      "severity": "high"
    },
    {
      "area": "interruption_recovery",
      "risk": "The app shows execution history and archives, but may not yet provide a strong guided recovery flow after Codex interruption without forcing users back to Project Center or a fresh run.",
      "severity": "high"
    },
    {
      "area": "profile_setup",
      "risk": "Technical model/profile fields can front-load failure and make recovery harder because users may not know whether interruption was caused by bad configuration, permissions, or runtime.",
      "severity": "medium"
    }
  ],
  "missing_user_feedback": [
    {
      "area": "permissions",
      "missing": "No explicit warning tier for destructive/system-wide actions such as recursive edits, shell commands, deletes, network access, or writes outside workspace."
    },
    {
      "area": "permissions",
      "missing": "No clear post-approval confirmation indicating what was executed, what changed, and whether changes can be reverted."
    },
    {
      "area": "approval_ux",
      "missing": "No inline explanation of approve vs decline vs cancel semantics and their effect on the current queued task."
    },
    {
      "area": "archive_ux",
      "missing": "No obvious user-facing message that archive snapshots can be used for recovery, comparison, or resume."
    },
    {
      "area": "archive_ux",
      "missing": "No visible status for archive completeness/integrity when interruption happens mid-run."
    },
    {
      "area": "runtime_unavailable",
      "missing": "Runtime unavailable state needs a primary CTA with explicit diagnosis and next steps: install Python sidecar, repair path, configure profile, or retry connection."
    },
    {
      "area": "runtime_unavailable",
      "missing": "No clear distinction between 'not installed', 'misconfigured', 'busy', 'crashed', and 'permission denied' runtime failures."
    },
    {
      "area": "retry_continue",
      "missing": "No explicit checkpoint/resume indicator showing the last completed macro/internal phase and what will happen on continue."
    },
    {
      "area": "retry_continue",
      "missing": "No user feedback about whether retry is idempotent or may duplicate side effects."
    },
    {
      "area": "interruption_recovery",
      "missing": "No dedicated interrupted-session banner/modal explaining that the workspace can be resumed without restarting and what state was preserved."
    },
    {
      "area": "interruption_recovery",
      "missing": "No one-click action to recover latest interrupted run from the current project."
    },
    {
      "area": "final_product",
      "missing": "Default recommendation of report may bias users away from resume/recovery-oriented next steps when execution stopped before completion."
    }
  ],
  "implementation-level fixes": [
    {
      "area": "permissions",
      "fix": "Add risk-tier badges on approval cards: 只读, 工作区写入, 工作区外写入, 执行命令, 网络访问, 删除/覆盖. Color-code and require secondary confirmation for high-risk tiers."
    },
    {
      "area": "permissions",
      "fix": "Show affected scope as normalized paths plus count of files/targets. For shell commands, render tokenized command preview and highlight dangerous flags."
    },
    {
      "area": "permissions",
      "fix": "After approval execution, append a result card with changed files, exit code, duration, and a '撤销建议/恢复入口' link when revert is possible."
    },
    {
      "area": "approval_ux",
      "fix": "Rename actions in Chinese-first UI to semantically distinct labels, e.g. '批准执行', '拒绝该步骤', '暂不处理'. Add tooltip/subtext describing queue behavior."
    },
    {
      "area": "approval_ux",
      "fix": "If user clicks decline, require optional reason and then have agent produce an adjusted plan instead of hard-failing silently."
    },
    {
      "area": "archive_ux",
      "fix": "Turn archive panel into recovery surface: '打开快照', '对比当前工作区', '从此状态继续', '导出快照'."
    },
    {
      "area": "archive_ux",
      "fix": "Persist per-checkpoint metadata: macro_phase, internal_phase, last_completed_action, pending_approvals, changed_paths, sidecar/runtime version, profile id, timestamp."
    },
    {
      "area": "archive_ux",
      "fix": "Mark interrupted snapshots with badge like '可恢复' or '快照不完整', based on whether checkpoint commit finished cleanly."
    },
    {
      "area": "runtime_unavailable",
      "fix": "Implement a dedicated empty/error state component with diagnosis-specific CTAs: '安装运行时', '重新检测', '打开配置', '查看日志', '使用浏览器回退对话框'."
    },
    {
      "area": "runtime_unavailable",
      "fix": "Map sidecar failures to actionable codes in Tauri->React events: NOT_INSTALLED, PATH_INVALID, CONFIG_MISSING, START_FAILED, CRASHED, PORT_BUSY, PERMISSION_DENIED, OFFLINE."
    },
    {
      "area": "runtime_unavailable",
      "fix": "Bundle a preflight check on project open and before run start; block execution with a repair checklist instead of failing mid-stream."
    },
    {
      "area": "retry_continue",
      "fix": "Separate controls: '重试该步骤', '从上个检查点继续', '重新开始本轮'. Each button should show exact resume point and side-effect warning."
    },
    {
      "area": "retry_continue",
      "fix": "Store deterministic run state in a local session record: run_id, project_id, phase pointers, event offset, approval decisions, workspace snapshot ref, pending prompt context."
    },
    {
      "area": "retry_continue",
      "fix": "On continue, rehydrate stream UI from persisted events and insert a synthetic banner: '已恢复到：宏阶段X / 内部阶段Y / 最近完成步骤Z'."
    },
    {
      "area": "interruption_recovery",
      "fix": "On app launch/project reopen, detect unfinished run and show a recovery banner with one-click actions: '继续', '查看中断原因', '从快照恢复', '放弃本次运行'."
    },
    {
      "area": "interruption_recovery",
      "fix": "Auto-save interruption reason and last heartbeat from sidecar; surface user-readable causes such as 'Codex连接中断', 'Python sidecar崩溃', '审批等待超时'."
    },
    {
      "area": "interruption_recovery",
      "fix": "Do not require returning to Project Center for recovery; keep resume controls in Workspace header and archive panel."
    },
    {
      "area": "profile_setup",
      "fix": "Collapse advanced profile/model settings behind '高级配置'. Add presets and inline validation so runtime/setup errors are caught before execution."
    },
    {
      "area": "final_product",
      "fix": "If run was interrupted or partially completed, suppress report-first recommendation and instead prioritize '继续执行' and '查看恢复选项'."
    }
  ]
}
